import unittest

from solucao import pegar
from solucao import area


class TestPegarComPadrao(unittest.TestCase):
    def test_pega_quando_a_chave_existe(self):
        """pegar devolve o valor da chave quando ela existe"""
        self.assertEqual(pegar({"a": 1}, "a", 0), 1)

    def test_devolve_o_padrao_sem_a_chave(self):
        """pegar devolve o padrao quando a chave nao existe"""
        self.assertEqual(pegar({"a": 1}, "b", 0), 0)

    def test_area_usa_o_lado_da_chave(self):
        """area devolve o lado da chave elevado ao quadrado"""
        self.assertEqual(area({"quadrado": 3}, "quadrado", 0), 9)

    def test_area_usa_o_padrao_sem_a_chave(self):
        """area usa o padrao como lado quando a chave nao existe"""
        self.assertEqual(area({"quadrado": 3}, "triangulo", 4), 16)

